-- Whether a live gift card exists (cache key `gc`): checkout configuration says so
-- (`giftCardsLive`), so a store that takes only cash can stop a key early when
-- no gift card could pay for it. Generated by scripts/cache-dep-triggers.ts
-- (CACHE_DEP_LATER_TABLES): a card's issue and removal, its status or expiry,
-- and its balance reaching or leaving zero advance `gc`; a partial redemption
-- does not.
CREATE TRIGGER `cdep_gift_cards_ins` AFTER INSERT ON `gift_cards`
BEGIN
  INSERT INTO `cache_dep` (`dep`, `seq`)
  SELECT key_rows.dep, COALESCE((SELECT `seq` FROM `cache_clock` WHERE `id` = 1), 0) + 1 FROM (SELECT key_list.value AS dep FROM json_each(json_array('gc', 't:gift_cards')) AS key_list) AS key_rows
  WHERE key_rows.dep IS NOT NULL AND COALESCE((SELECT `coarse` FROM `cache_clock` WHERE `id` = 1), 0) = 0
  UNION ALL SELECT 'store', COALESCE((SELECT `seq` FROM `cache_clock` WHERE `id` = 1), 0) + 1 WHERE COALESCE((SELECT `coarse` FROM `cache_clock` WHERE `id` = 1), 0) = 1
  ON CONFLICT (`dep`) DO UPDATE SET `seq` = excluded.`seq`;
END;
